// Analytics utility functions for Global Pickups
// This file centralizes all analytics-related code

/**
 * Initialize analytics with proper user consent checks
 */
export const initializeAnalytics = () => {
  // Check for user consent (implement with cookie consent system)
  const hasConsent = localStorage.getItem('analytics-consent') === 'true';
  
  if (hasConsent) {
    // Enable analytics tracking
    window.gtag('consent', 'update', {
      'analytics_storage': 'granted'
    });
  } else {
    // Disable analytics tracking until consent is given
    window.gtag('consent', 'default', {
      'analytics_storage': 'denied'
    });
  }
};

/**
 * Track page views in the application
 * @param {string} path - The current page path
 * @param {string} title - The page title
 */
export const trackPageView = (path, title) => {
  if (!window.gtag) return;
  
  window.gtag('event', 'page_view', {
    page_path: path,
    page_title: title,
    page_location: window.location.href
  });
};

/**
 * Track user events in the application
 * @param {string} action - The action name (e.g., 'click', 'submit')
 * @param {string} category - The event category (e.g., 'travel_plan', 'item_request')
 * @param {object} additionalParams - Any additional parameters to track
 */
export const trackEvent = (action, category, additionalParams = {}) => {
  if (!window.gtag) return;
  
  window.gtag('event', action, {
    event_category: category,
    ...additionalParams
  });
};

/**
 * Set user properties once user is identified
 * @param {string} userId - User's ID (hashed for privacy)
 * @param {object} properties - User properties to track
 */
export const setUserProperties = (userId, properties = {}) => {
  if (!window.gtag) return;
  
  // Never send raw PII - ensure userId is hashed
  window.gtag('set', 'user_properties', {
    user_id: userId,
    ...properties
  });
};

/**
 * Update consent status based on user choice
 * @param {boolean} hasConsent - Whether user has given consent
 */
export const updateConsentStatus = (hasConsent) => {
  localStorage.setItem('analytics-consent', hasConsent.toString());
  
  window.gtag('consent', 'update', {
    'analytics_storage': hasConsent ? 'granted' : 'denied'
  });
};

/**
 * Track web vitals metrics
 * @param {Object} metric - Web vitals metric object
 */
export const sendWebVitalsToAnalytics = (metric) => {
  const { name, delta, id } = metric;
  
  if (!window.gtag) return;
  
  window.gtag('event', name, {
    event_category: 'Web Vitals',
    event_label: id,
    value: Math.round(name === 'CLS' ? delta * 1000 : delta),
    non_interaction: true,
  });
};